class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        dp = [[0] * (k+1) for _ in range(n)]

        # Base case: first subarray
        for i in range(m):
            dp[i][1] = nums[i]

        # Fill the DP table
        for i in range(m, n):
            for j in range(2, k+1):
                dp[i][j] = max(dp[i-m][j-1] + nums[i], dp[i-1][j])

        return max(dp[-1])

