class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        if len(nums) < k*m:
            return float('-inf')

        dp = [[0]*m for _ in range(k)]
        prefix_sum = [0]
        for i in range(len(nums)):
            prefix_sum.append(prefix_sum[-1] + nums[i])

        for i in range(1, k+1):
            for j in range(m):
                if j == 0:
                    dp[i][j] = prefix_sum[i+m-1] - prefix_sum[i-1]
                else:
                    dp[i][j] = max(dp[i-1][j], dp[i-1][j-1] + prefix_sum[i+m-1] - prefix_sum[i-1])

        return dp[k][m-1]

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        if n < k * m:
            return -1

        # Initialize prefix sums
        prefix_sums = [0] * (n + 1)
        for i in range(1, n + 1):
            prefix_sums[i] = prefix_sums[i - 1] + nums[i - 1]

        # Dynamic programming table to store maximum sum of k subarrays ending at index i
        dp = [[0] * (k + 1) for _ in range(n + 1)]

        # Fill the dp table
        for i in range(1, n + 1):
            for j in range(1, min(k + 1, i // m + 1)):
                dp[i][j] = max(dp[i - 1][j], dp[i - m][j - 1] + prefix_sums[i] - prefix_sums[i - m])

        # Return the result
        return dp[n][k]

