class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        if n < k * m:
            return -1

        # Initialize variables to store cumulative sums
        cum_sum = [0] * (n + 1)
        for i in range(1, n + 1):
            cum_sum[i] = cum_sum[i - 1] + nums[i - 1]

        # Initialize variables to store results for different lengths
        dp = [[0] * (m + 1) for _ in range(k + 1)]

        # Fill the DP table
        for i in range(1, k + 1):
            for j in range(m + 1):
                if i == 1 and j == 1:
                    dp[i][j] = cum_sum[i] - cum_sum[j - 1]
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - 1] + cum_sum[i] - cum_sum[j - 1])

        return dp[k][m]

