class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        # Calculate prefix sums for convenience
        pre_sum = [0]
        for num in nums:
            pre_sum.append(pre_sum[-1] + num)

        # Initialize variables to keep track of the maximum sum and the current window's sum
        max_sum = float('-inf')
        current_sum = 0

        # Iterate through the array starting from index k
        for i in range(k):
            current_sum += pre_sum[i + m] - pre_sum[i]
            if current_sum > max_sum:
                max_sum = current_sum

        # Use sliding window to find the maximum sum of k subarrays
        for i in range(k, len(nums)):
            current_sum += pre_sum[i + m] - pre_sum[i - k]
            if current_sum > max_sum:
                max_sum = current_sum

        return max_sum

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        if n < k * m:
            return -1

        # Initialize prefix sums
        pre_sum = [0] * (n + 1)
        for i in range(1, n + 1):
            pre_sum[i] = pre_sum[i - 1] + nums[i - 1]

        # Initialize dp table
        dp = [[0] * (m + 1) for _ in range(n)]

        # Fill dp table
        for i in range(k, n + 1):
            for j in range(m):
                if j == 0:
                    dp[i][j] = pre_sum[i] - pre_sum[i - k]
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i - k][j - 1] + pre_sum[i] - pre_sum[i - k])

        # Find the maximum sum of k non-overlapping subarrays
        result = 0
        for i in range(k, n + 1):
            result = max(result, dp[i][m - 1])

        return result

