class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        if n < k * m:
            return -inf

        dp = [[0] * (m+1) for _ in range(n)]

        # Initialize the first subarray
        for i in range(m):
            dp[0][i+1] = nums[i]

        # Fill the dp table
        for i in range(1, n):
            for j in range(1, min(i+1, k*m)):
                if j > m:
                    dp[i][j] = dp[i-1][j]  # No overlap
                else:
                    dp[i][j] = max(dp[i-1][j], dp[i-m][j-1] + nums[i])

        return dp[n-1][-1]

