class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        dp = [[0] * (k+1) for _ in range(n)]

        # Initialize the first row
        for i in range(k):
            if i < m:
                dp[0][i] = sum(nums[:i+1])
            else:
                dp[0][i] = dp[0][i-m] + nums[i]

        # Fill the DP table
        for i in range(1, n):
            for j in range(k):
                if j < m:
                    dp[i][j] = max(dp[i-1][j], dp[i-1][j+m] + nums[i])
                else:
                    dp[i][j] = max(dp[i-1][j], dp[i-1][j-m] + nums[i] - nums[i-k])

        return dp[n-1][k-1]

