class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        # Initialize variables to store cumulative sums and results
        cumsums = []
        for i in range(len(nums)):
            if i == 0:
                cumsums.append(nums[i])
            else:
                cumsums.append(cumsums[-1] + nums[i])

        # Calculate the prefix sums of cumulative sums
        prefix_sums = [0] * len(cumsums)
        for i in range(1, len(prefix_sums)):
            prefix_sums[i] = prefix_sums[i - 1] + cumsums[i]

        # Use dynamic programming to find the maximum sum of k non-overlapping subarrays of length at least m
        @cache
        def dp(i):
            if i >= len(cumsums):
                return 0
            result = float('-inf')
            for j in range(i, min(len(cumsums), i + m)):
                result = max(result, prefix_sums[j] - prefix_sums[i] + dp(j + k))
            return result

        return dp(0)

