    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        if n < k * m:
            return -float('inf')

        dp = [[0] * m for _ in range(n)]

        # Initialize the first row
        for j in range(m):
            dp[0][j] = nums[j]

        # Fill the DP table
        for i in range(1, n):
            for j in range(m):
                if j == 0:
                    dp[i][j] = dp[i-1][j] + nums[i]
                else:
                    dp[i][j] = max(dp[i-1][j], dp[i-m][j-1]) + nums[i]

        # Find the maximum sum of k non-overlapping subarrays
        max_sum = float('-inf')
        for i in range(n-k+1):
            max_sum = max(max_sum, dp[i+k-1][-1])

        return max_sum

