class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        indices = defaultdict(list)
        for i, num in enumerate(nums):
            indices[num].append(i)

        ans = []
        for q in queries:
            if q not in indices:
                ans.append(-1)
                continue

            closest_index = float('inf')
            for idx in indices[q]:
                if idx == q:
                    closest_index = 0
                    break
                if abs(idx - q) < closest_index:
                    closest_index = abs(idx - q)

            ans.append(closest_index)

        return ans

