    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        ans = []
        pos = {}
        for i in range(n):
            if nums[i] not in pos:
                pos[nums[i]] = [i]
            else:
                pos[nums[i]].append(i)

        for q in queries:
            if q in pos:
                distances = []
                for p in pos[q]:
                    if p > q:
                        distances.append(n-p)
                    else:
                        distances.append(p)
                ans.append(min(distances))
            else:
                ans.append(-1)
        return ans

