class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        # Create a dictionary to store the indices of each number
        num_indices = defaultdict(list)
        for i, num in enumerate(nums):
            num_indices[num].append(i)

        result = []
        for q in queries:
            # Find the leftmost occurrence of the current number
            left_index = bisect.bisect_left(num_indices[q], q)
            if left_index < len(num_indices[q]):
                left_dist = abs(q - num_indices[q][left_index])
            else:
                left_dist = len(nums) + abs(q - num_indices[q][-1])

            # Find the rightmost occurrence of the current number
            right_index = bisect.bisect_right(num_indices[q], q)
            if right_index > 0:
                right_dist = abs(q - num_indices[q][right_index - 1])
            else:
                right_dist = len(nums) + abs(q - num_indices[q][0])

            # Take the minimum distance
            result.append(min(left_dist, right_dist))

        return result

class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        ans = [-1] * len(queries)
        # Create a dictionary to store indices of each number
        num_indices = {}
        for i, num in enumerate(nums):
            if num not in num_indices:
                num_indices[num] = []
            num_indices[num].append(i)

        for i, q in enumerate(queries):
            if q in num_indices:
                indices = num_indices[q]
                # Find the closest index to the current query index
                left_index = bisect.bisect_left(indices, i)
                right_index = bisect.bisect_right(indices, i)

                # Calculate distances from both sides
                left_distance = i - indices[left_index] if left_index > 0 else n + i - indices[left_index]
                right_distance = indices[right_index] - i if right_index < n else indices[right_index] - i + n

                # Update the answer based on the smaller distance
                ans[i] = min(left_distance, right_distance)

        return ans

