class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        pos = defaultdict(list)

        # Find the positions of each number in the circular array
        for i, num in enumerate(nums):
            pos[num].append(i % n)

        ans = []

        # For each query, find the closest occurrence of the query's value
        for q in queries:
            if q not in pos:
                ans.append(-1)
            else:
                indices = pos[q]
                # Find the closest index using binary search
                left = bisect.bisect_left(indices, q)
                right = bisect.bisect_right(indices, q)

                if left > 0:
                    ans.append(min(abs(q - indices[left - 1]), abs(q - indices[left])))
                elif right < n:
                    ans.append(min(abs(q - indices[right]), abs(q - indices[right - 1])))
                else:
                    ans.append(-1)

        return ans

class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        # Create a dictionary to store the indices of each number
        num_indices = {}
        for i, num in enumerate(nums):
            if num not in num_indices:
                num_indices[num] = []
            num_indices[num].append(i)

        # Process each query
        answers = []
        for q in queries:
            # Find the indices of the current number
            indices = num_indices.get(q, [])

            # Calculate the distances from the current index to the indices of the current number
            distances = [abs(idx - q) for idx in indices]

            # If there are multiple indices, find the minimum distance
            if len(distances) > 1:
                min_distance = min(distances)
            else:
                min_distance = float('inf')

            # Append the result to the answers list
            answers.append(min_distance if min_distance != float('inf') else -1)

        return answers

