class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        min_dist = [-1] * n

        # Find the first occurrence of each number
        num_indices = defaultdict(list)
        for i, num in enumerate(nums):
            num_indices[num].append(i)

        # Calculate the minimum distance for each query
        for i, q in enumerate(queries):
            if q not in num_indices:
                continue

            indices = num_indices[q]
            left_index = bisect.bisect_left(indices, i)
            right_index = bisect.bisect_right(indices, i)

            if left_index > 0:
                min_dist[i] = min(min_dist[i], abs(indices[left_index - 1] - i))
            if right_index < len(indices):
                min_dist[i] = min(min_dist[i], abs(indices[right_index] - i))

            if left_index < len(indices) - 1:
                min_dist[i] = min(min_dist[i], abs(indices[left_index + 1] - i))
            if right_index > 0:
                min_dist[i] = min(min_dist[i], abs(indices[right_index - 1] - i))

        return min_dist

