            indices = pos[q]
            if len(indices) > 1:
                min_dist = float('inf')
                for i in range(len(indices)):
                    if i == 0:
                        min_dist = min(min_dist, indices[i + 1] - indices[i])
                    elif i == len(indices) - 1:
                        min_dist = min(min_dist, n - indices[i] + indices[i - 1])
                    else:
                        min_dist = min(min_dist, min(indices[i + 1] - indices[i], indices[i] - indices[i - 1]))
