class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        # Create a dictionary to store the last occurrence of each number
        last_occurrence = {num: i for i, num in enumerate(nums)}

        # Initialize the result list
        result = []

        # Iterate through each query
        for q in queries:
            min_distance = float('inf')

            # Check for the current number directly
            if q in last_occurrence:
                min_distance = 0

            # Check for the previous occurrence of the current number
            if q > 0:
                min_distance = min(min_distance, last_occurrence[q] - q)

            # Check for the next occurrence of the current number
            if q < len(nums) - 1:
                min_distance = min(min_distance, q - last_occurrence[q])

            # Append the result for the current query
            result.append(min_distance if min_distance != float('inf') else -1)

        return result

