class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        ans = [-1] * len(queries)
        idxs = defaultdict(list)
        for i, num in enumerate(nums):
            idxs[num].append(i)

        for i, q in enumerate(queries):
            if q not in idxs:
                continue

            # Find the leftmost occurrence of q
            l = bisect_left(idxs[q], q)
            if l > 0:
                ans[i] = min(ans[i], abs(q - idxs[q][l-1]))

            # Find the rightmost occurrence of q
            r = bisect_right(idxs[q], q)
            if r < len(idxs[q]):
                ans[i] = min(ans[i], abs(q - idxs[q][r]))

        return ans

