class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        left = defaultdict(list)
        right = defaultdict(list)

        # Build left and right arrays
        for i in range(n):
            left[nums[i]].append(i)
            right[nums[i]].append(i)

        ans = []
        for q in queries:
            if q not in left or q not in right:
                ans.append(-1)
            else:
                l_idx = bisect.bisect_left(left[q], q)
                r_idx = bisect.bisect_right(right[q], q)

                # Check if there is a left neighbor
                if l_idx > 0:
                    ans.append(min(abs(q - left[q][l_idx - 1]), abs(q - left[q][l_idx])))
                else:
                    ans.append(abs(q - left[q][-1]))

                # Check if there is a right neighbor
                if r_idx < n:
                    ans.append(min(abs(q - right[q][r_idx + 1]), abs(q - right[q][r_idx])))
                else:
                    ans.append(abs(q - right[q][0]))

        return ans

