class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        left = [-1] * n
        right = [-1] * n

        # Find leftmost occurrence of each number
        last_index = -1
        for i in range(n):
            if nums[i] != nums[last_index]:
                last_index = i
            left[i] = last_index

        # Find rightmost occurrence of each number
        last_index = n
        for i in range(n-1, -1, -1):
            if nums[i] != nums[last_index]:
                last_index = i
            right[i] = last_index

        ans = []
        for q in queries:
            if left[q] == -1 or right[q] == -1:
                ans.append(-1)
            else:
                ans.append(min(abs(left[q] - q), abs(right[q] - q)))

        return ans

