class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        # Create a dictionary to store the last occurrence of each number
        num_indices = {}

        # Populate the dictionary with the last occurrence of each number
        for i, num in enumerate(nums):
            if num not in num_indices:
                num_indices[num] = i

        # Initialize the result list
        result = []

        # Iterate through each query
        for q in queries:
            # Find the first occurrence of the current number before the query index
            left_index = max(num_indices.get(q, -1), -1)

            # Find the first occurrence of the current number after the query index
            right_index = min(len(nums) + num_indices.get(q, -1), len(nums))

            # Calculate the distance between the query index and the closest occurrences
            if left_index != -1 and right_index != len(nums):
                distance = min(right_index - q, q - left_index)
            elif left_index != -1:
                distance = len(nums) - q + left_index
            elif right_index != len(nums):
                distance = q - right_index
            else:
                distance = -1

            # Append the calculated distance to the result list
            result.append(distance)

        return result

