class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        left = defaultdict(list)
        right = defaultdict(list)

        # Build left and right dictionaries
        for i in range(n):
            left[nums[i]].append(i)
            right[nums[i]].append(i)

        ans = []

        # Process each query
        for q in queries:
            if q not in left or q not in right:
                ans.append(-1)
            else:
                left_values = left[q]
                right_values = right[q]

                # Find the closest value on the left side
                if left_values[-1] == q:
                    ans.append(0)
                else:
                    min_distance = float('inf')
                    for v in left_values:
                        if abs(v - q) < min_distance:
                            min_distance = abs(v - q)
                    ans.append(min_distance)

