                elif s[i] == 'S':
                    dp[i+1][j-1] = max(dp[i+1][j-1], dp[i][j] + 1)
                elif s[i] == 'E':
                    dp[i+1][j] = max(dp[i+1][j], dp[i][j] + 1)
                elif s[i] == 'W':
                    dp[i+1][j] = max(dp[i+1][j], dp[i][j] + 1)

