class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        n = len(s)
        dp = [[-1 for _ in range(k+1)] for _ in range(n)]

        # Base case: if we have no moves left, the maximum distance is 0
        for i in range(n):
            dp[i][0] = 0

        # Fill the DP table
        for i in range(1, n):
            for j in range(1, k+1):
                # If we can make one more move, take the best of moving north or south
                if i > 0 and s[i-1] != 'N':
                    dp[i][j] = max(dp[i-1][j], dp[i-1][j-1])
                # If we can make one more move, take the best of moving east or west
                if i > 0 and s[i-1] != 'W':
                    dp[i][j] = max(dp[i][j], dp[i-1][j+1])

                # If we can make two more moves, take the best of moving north-south or east-west
                if i > 1 and s[i-1] != 'N' and s[i-2] != 'S':
                    dp[i][j] = max(dp[i][j], dp[i-2][j-1])
                if i > 1 and s[i-1] != 'W' and s[i-2] != 'E':
                    dp[i][j] = max(dp[i][j], dp[i-2][j+1])

        # The maximum Manhattan distance is the maximum value in the last row
        return max(dp[n-1])

