class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # Combine both strings into one to simplify checking for palindromes
        combined_string = s + t

        # Helper function to check if a string is a palindrome
        def is_palindrome(s):
            return s == s[::-1]

        # Initialize variables to keep track of the result
        max_length = 0

        # Iterate through each possible starting index of the first half of the combined string
        for i in range(len(combined_string)):
            # Check if the current character forms a palindrome when added to the second half
            if combined_string[i] == combined_string[-(i+1)] and is_palindrome(combined_string[:i]):
                max_length = max(max_length, i * 2)

        # If the combined string is already a palindrome, add one more to the result
        if is_palindrome(combined_string):
            max_length += 1

        return max_length

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # Check if either string is empty
        if not s or not t:
            return 0

        # Concatenate the strings to form a new string
        combined_string = s + t

        # Initialize variables to keep track of the result and the longest palindromic subsequence length
        result = 0
        dp = [[0] * len(combined_string) for _ in range(len(combined_string))]

        # Fill the DP table
        for i in range(1, len(combined_string)):
            for j in range(i):
                if combined_string[i] == combined_string[j]:
                    dp[i][j] = dp[i-1][j+1] + 2
                    result = max(result, dp[i][j])
                else:
                    dp[i][j] = max(dp[i-1][j], dp[i][j-1])

        return result

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # Create a set of characters from both strings
        chars = set(s + t)
        n = len(chars)

        # If there's only one character, it's already a palindrome
        if n == 1:
            return 1

        # Initialize a DP table with zeros
        dp = [[0] * n for _ in range(n)]

        # Fill the DP table
        for i in range(n):
            for j in range(i, n):
                # If characters at positions i and j are the same
                if s[i] == t[j]:
                    # If they're adjacent or not, add 2 to the result
                    if i == j or i + 1 == j:
                        dp[i][j] = 2
                    else:
                        dp[i][j] = dp[i + 1][j - 1] + 2
                else:
                    # Otherwise, take the maximum of the two possible cases
                    dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

        # The length of the longest palindromic subsequence is in dp[0][n-1]
        return dp[0][n - 1]

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # Create a set to store unique characters from both strings
        unique_chars = set(s + t)

        # If there are no unique characters, return 0
        if not unique_chars:
            return 0

        # Initialize variables to keep track of the longest palindrome
        max_length = 0

        # Iterate through each unique character
        for char in unique_chars:
            # Check if the character appears at least twice in either string
            if s.count(char) >= 2 or t.count(char) >= 2:
                # Calculate the maximum length of the palindrome using the character
                max_length = max(max_length, len(s) + len(t) - 2 * s.count(char))

        return max_length

def min_xor_path(edges):
    n = len(edges)
    graph = [[] for _ in range(n)]

    # Build the graph
    for u, v, w in edges:
        graph[u - 1].append((v - 1, w))
        graph[v - 1].append((u - 1, w))

    def dfs(u, parent, xor_value):
        if u == n - 1:
            return xor_value

        min_xor = float('inf')
        for v, w in graph[u]:
            if v != parent:
                new_xor = xor_value ^ w
                min_xor = min(min_xor, dfs(v, u, new_xor))

        return min_xor

    return dfs(0, None, 0)

