from collections import defaultdict

def xor_path_edges(graph, start, end):
    def dfs(node, path_xor, visited):
        visited.add(node)
        for neighbor, weight in graph[node]:
            if neighbor not in visited:
                new_path_xor = path_xor ^ weight
                dfs(neighbor, new_path_xor, visited)

    visited = set()
    dfs(start, 0, visited)
    return max(path_xor for path_xor in visited)

